def get_seqs(
    self,
    status: Optional[SequenceStatus] = None,
) -> list[Sequence]:
    if status is None:
        return self.seqs

    if self.is_single_seq:
        return self.seqs if self.first_seq.status == status else []

    return [seq for seq in self.seqs if seq.status == status]

