class LogitsProcessor(ABC):

    @abstractmethod
    def __init__(self, vllm_config: "VllmConfig", device: torch.device,
                 is_pin_memory: bool) -> None:
        raise NotImplementedError

    @abstractmethod
    def apply(self, logits: torch.Tensor) -> torch.Tensor:
        raise NotImplementedError

    @abstractmethod
    def is_argmax_invariant(self) -> bool:
        """True if logits processor has no impact on the
        argmax computation in greedy sampling.
        NOTE: may or may not have the same value for all
        instances of a given LogitsProcessor subclass,
        depending on subclass implementation.
        """
        raise NotImplementedError

    @abstractmethod
    def update_state(
        self,
        batch_update: Optional["BatchUpdate"],
    ) -> None:
        """Called when there are new output tokens, prior
        to each forward pass.

        Args:
            batch_update is non-None iff there have been
            changes to the batch makeup.
        """
        raise NotImplementedError

        )
        self._removed = []
        self.moved = []
        self.added = []
        return batch_update


class LogitsProcessors:
    """Encapsulates initialized logitsproc objects."""

    def __init__(
            self,
            logitsprocs: Optional[Iterator["LogitsProcessor"]] = None) -> None:
        self.argmax_invariant: list[LogitsProcessor] = []
        self.non_argmax_invariant: list[LogitsProcessor] = []
        if logitsprocs:
            for logitproc in logitsprocs:
                (self.argmax_invariant if logitproc.is_argmax_invariant() else
                 self.non_argmax_invariant).append(logitproc)

    @property
    def all(self) -> Iterator["LogitsProcessor"]:
        """Iterator over all logits processors."""
        return chain(self.argmax_invariant, self.non_argmax_invariant)

    if isinstance(obj, np.ndarray) and obj.dtype.kind not in ('O', 'V'):
        return self._encode_ndarray(obj)

    if isinstance(obj, slice):
        # We are assuming only int-based values will be used here.
        return tuple(
            int(v) if v is not None else None
            for v in (obj.start, obj.stop, obj.step))

    if isinstance(obj, MultiModalKwargsItem):
        return self._encode_mm_item(obj)

    if isinstance(obj, MultiModalKwargs):
        return [
            self._encode_mm_item(item)
            for itemlist in obj._items_by_modality.values()
            for item in itemlist
        ]

    if isinstance(obj, UtilityResult):
        result = obj.result
        if not envs.VLLM_ALLOW_INSECURE_SERIALIZATION:
            return None, result
        # Since utility results are not strongly typed, we also encode
        # the type (or a list of types in the case it's a list) to
        # help with correct msgspec deserialization.
        return _typestr(result) if type(result) is not list else [
            _typestr(v) for v in result
        ], result

    if not envs.VLLM_ALLOW_INSECURE_SERIALIZATION:
        raise TypeError(f"Object of type {type(obj)} is not serializable"
                        "Set VLLM_ALLOW_INSECURE_SERIALIZATION=1 to allow "
                        "fallback to pickle-based serialization.")

    if isinstance(obj, FunctionType):
        # `pickle` is generally faster than cloudpickle, but can have
        # problems serializing methods.
        return msgpack.Ext(CUSTOM_TYPE_CLOUDPICKLE, cloudpickle.dumps(obj))

    return msgpack.Ext(CUSTOM_TYPE_PICKLE,
                       pickle.dumps(obj, protocol=pickle.HIGHEST_PROTOCOL))

def _encode_ndarray(
    self, obj: np.ndarray
) -> tuple[str, tuple[int, ...], Union[int, memoryview]]:

