                                  engine_idx)

def log(self):
    for per_engine_loggers in self.per_engine_logger_dict.values():
        for logger in per_engine_loggers:
            logger.log()

def log_engine_initialized(self):
    self.prometheus_logger.log_engine_initialized()

    for per_engine_loggers in self.per_engine_logger_dict.values():
        for logger in per_engine_loggers:
            logger.log_engine_initialized()

