            if self.ext_pw_kernel_size > 1:
                self.fix_len1 = True
            else:
                self.fix_len1 = False
        else:
            self.ext_pw_conv_1d = nn.Conv1d(
                self.input_dim,
                self.ext_pw_out_channel,
                self.ext_pw_kernel_size,
                1,
                padding=(self.ext_pw_kernel_size - 1) // 2,
            )
            self.fix_len1 = False

        if self.linear_glu_in_convm:
            self.glu = GLULinear(
                self.input_dim,
                self.ext_pw_out_channel,
                self.glu_type,
                self.bias_in_glu,
            )

        else:
            self.glu = GLUPointWiseConv(
                self.input_dim,
                self.ext_pw_out_channel,
                self.ext_pw_kernel_size,
                self.glu_type,
                self.bias_in_glu,
                self.causal,
