                                             concat=True)
        video_num_patches = flatten_bn(video_num_patches, concat=True)
        expected_h = expected_w = self.config.vision_config.image_size
        resolve_bindings = {"h": expected_h, "w": expected_w}

        return InternVLVideoPixelInputs(
