def _get_parent_and_attr(self, root: torch.nn.Module, dotted_name: str):
    """Return (parent_module, final_attr_name) for a dotted module path."""
    names = dotted_name.split('.')
    parent = root
    for n in names[:-1]:
        parent = getattr(parent, n)
    return parent, names[-1]

