    for _, seq_to_slot_map in (
            self.minimax_cache.cache_indices_mapping.items()):
        seq_to_slot_maps.update(seq_to_slot_map)

    slots_to_clear = []
    for _prefill_id in range(getattr(attn_metadata, "num_prefills", 0)):
