    # Make sure we use the nvcc from CUDA_HOME
    if _is_cuda():
        cmake_args += [f'-DCMAKE_CUDA_COMPILER={CUDA_HOME}/bin/nvcc']
    subprocess.check_call(
        ['cmake', ext.cmake_lists_dir, *build_tool, *cmake_args],
        cwd=self.build_temp)

